contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 amount) public {
        require(amount > 0);

        // The test contract holds no shares, so grant ourselves an ample
        // allowance first; the transferFrom must still fail on balance.
        c.approve(address(this), type(uint256).max); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transferFrom(address(this), to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted &&
            c.balanceOf(address(this)) == 0 &&
            c.balanceOf(to) == 0
        );
    }

    receive() external payable {}
}

